import React from 'react';
import { RouterProvider } from 'react-router';
import { router } from './routes';
import { AppProvider } from './context/AppContext';

// No pongas aquí fetch a Supabase: App solo envuelve la app en contexto + rutas.
// Usa una página (p. ej. /supabase → SupabaseExample) como indica Supabase pero sin reemplazar el router.

export default function App() {
  return (
    <AppProvider>
      <RouterProvider router={router} />
    </AppProvider>
  );
}

import React from 'react';
import { RouterProvider } from 'react-router';
import { GoogleOAuthProvider } from '@react-oauth/google';
import { router } from './routes';
import { AppProvider } from './context/AppContext';
import { AuthProvider } from './context/AuthContext';

// IMPORTANTE: Obtén tu Google Client ID en https://console.cloud.google.com
const GOOGLE_CLIENT_ID = import.meta.env.VITE_GOOGLE_CLIENT_ID || '';

export default function App() {
  if (!GOOGLE_CLIENT_ID) {
    return <div className="p-4 text-red-600">Error: VITE_GOOGLE_CLIENT_ID no configurado</div>;
  }

  return (
    <GoogleOAuthProvider clientId={GOOGLE_CLIENT_ID}>
      <AuthProvider>
        <AppProvider>
          <RouterProvider router={router} />
        </AppProvider>
      </AuthProvider>
    </GoogleOAuthProvider>
  );
}

import React from 'react';
import { Outlet, NavLink } from 'react-router';
import { Home, Scissors, Users, Sparkles, TrendingUp } from 'lucide-react';

export const Layout = () => {
  const navItems = [
    { path: '/', icon: Home, label: 'Inicio' },
    { path: '/produccion', icon: Scissors, label: 'Producción' },
    { path: '/empleados', icon: Users, label: 'Empleados' },
    { path: '/aseo', icon: Sparkles, label: 'Aseo' },
    { path: '/rendimiento', icon: TrendingUp, label: 'Desempeño' },
  ];

  return (
    <div className="flex min-h-dvh flex-col bg-slate-50 text-slate-800 font-sans md:flex-row">
      <main className="order-1 flex min-h-0 min-w-0 flex-1 flex-col pb-[calc(5.5rem+env(safe-area-inset-bottom,0px))] md:order-2 md:pb-0">
        <div className="mx-auto w-full max-w-5xl flex-1 p-4 md:p-8">
          <Outlet />
        </div>
      </main>

      <aside
        className={[
          'order-2 z-50 flex shrink-0 justify-center',
          'fixed inset-x-3 bottom-[max(0.75rem,env(safe-area-inset-bottom,0px))] max-w-lg mx-auto',
          'rounded-2xl border border-teal-700/20 bg-teal-800/95 p-2 shadow-2xl backdrop-blur-md',
          'md:static md:inset-auto md:mx-0 md:max-w-none md:min-h-dvh md:w-[5.25rem] md:flex-col md:justify-start md:rounded-none md:border-0 md:border-r md:border-slate-200 md:bg-white md:p-3 md:shadow-sm md:backdrop-blur-none lg:w-28',
        ].join(' ')}
      >
        <div className="hidden md:flex md:flex-col md:items-center md:pt-6 md:pb-4 text-teal-600">
          <Scissors size={36} strokeWidth={1.5} className="shrink-0" />
          <span className="mt-2 text-center text-[10px] font-bold uppercase tracking-widest leading-tight">
            Taller
          </span>
        </div>

        <nav className="flex w-full flex-1 items-center justify-around gap-1 px-1 py-1 md:flex md:flex-col md:justify-start md:gap-2 md:px-0 md:py-4">
          {navItems.map(({ path, icon: Icon, label }) => (
            <NavLink
              key={path}
              to={path}
              end={path === '/'}
              className={({ isActive }) =>
                [
                  'flex shrink-0 flex-col items-center justify-center rounded-xl transition-all duration-200',
                  'h-14 w-[4.25rem] sm:w-16 md:h-[4.25rem] md:w-full md:max-w-[4.5rem] md:mx-auto',
                  isActive
                    ? 'bg-amber-400 text-teal-900 shadow-inner md:bg-teal-50 md:text-teal-700 md:shadow-md'
                    : 'text-teal-50 hover:bg-teal-700/50 md:text-slate-500 md:hover:bg-slate-100 md:hover:text-teal-700',
                ].join(' ')
              }
            >
              <Icon size={24} strokeWidth={2} className="mb-0.5 md:size-[26px]" />
              <span className="max-w-full truncate px-0.5 text-[9px] font-semibold tracking-wide md:text-[10px]">
                {label}
              </span>
            </NavLink>
          ))}
        </nav>
      </aside>
    </div>
  );
};

import React from 'react';
import { Outlet, NavLink, useNavigate } from 'react-router';
import { Home, Scissors, Users, Sparkles, TrendingUp, LogOut } from 'lucide-react';
import { useAuth } from '../context/AuthContext';

export const Layout = () => {
  const navigate = useNavigate();
  const { logout, user } = useAuth();

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const navItems = [
    { path: '/', icon: Home, label: 'Inicio' },
    { path: '/produccion', icon: Scissors, label: 'Producción' },
    { path: '/empleados', icon: Users, label: 'Empleados' },
    { path: '/aseo', icon: Sparkles, label: 'Aseo' },
    { path: '/rendimiento', icon: TrendingUp, label: 'Desempeño' },
  ];

  return (
    <div className="flex min-h-dvh flex-col bg-slate-50 text-slate-800 font-sans md:flex-row">
      <main className="order-1 flex min-h-0 min-w-0 flex-1 flex-col pb-[calc(5.5rem+env(safe-area-inset-bottom,0px))] md:order-2 md:pb-0">
        <div className="mx-auto w-full max-w-5xl flex-1 p-4 md:p-8">
          <Outlet />
        </div>
      </main>

      <aside
        className={[
          'order-2 z-50 flex shrink-0 justify-center',
          'fixed inset-x-3 bottom-[max(0.75rem,env(safe-area-inset-bottom,0px))] max-w-lg mx-auto',
          'rounded-2xl border border-teal-700/20 bg-teal-800/95 p-2 shadow-2xl backdrop-blur-md',
          'md:static md:inset-auto md:mx-0 md:max-w-none md:min-h-dvh md:w-[5.25rem] md:flex-col md:justify-start md:rounded-none md:border-0 md:border-r md:border-slate-200 md:bg-white md:p-3 md:shadow-sm md:backdrop-blur-none lg:w-28',
        ].join(' ')}
      >
        <div className="hidden md:flex md:flex-col md:items-center md:pt-6 md:pb-4 text-teal-600">
          <Scissors size={36} strokeWidth={1.5} className="shrink-0" />
          <span className="mt-2 text-center text-[10px] font-bold uppercase tracking-widest leading-tight">
            Taller
          </span>
        </div>

        <nav className="flex w-full flex-1 items-center justify-around gap-1 px-1 py-1 md:flex md:flex-col md:justify-start md:gap-2 md:px-0 md:py-4">
          {navItems.map(({ path, icon: Icon, label }) => (
            <NavLink
              key={path}
              to={path}
              end={path === '/'}
              className={({ isActive }) =>
                [
                  'flex shrink-0 flex-col items-center justify-center rounded-xl transition-all duration-200',
                  'h-14 w-[4.25rem] sm:w-16 md:h-[4.25rem] md:w-full md:max-w-[4.5rem] md:mx-auto',
                  isActive
                    ? 'bg-amber-400 text-teal-900 shadow-inner md:bg-teal-50 md:text-teal-700 md:shadow-md'
                    : 'text-teal-50 hover:bg-teal-700/50 md:text-slate-500 md:hover:bg-slate-100 md:hover:text-teal-700',
                ].join(' ')
              }
            >
              <Icon size={24} strokeWidth={2} className="mb-0.5 md:size-[26px]" />
              <span className="max-w-full truncate px-0.5 text-[9px] font-semibold tracking-wide md:text-[10px]">
                {label}
              </span>
            </NavLink>
          ))}
        </nav>

        <div className="hidden md:flex md:flex-col md:items-center md:gap-2 md:border-t md:border-slate-200 md:pt-3 md:mt-auto">
          {user && (
            <div className="text-center">
              {user.picture && (
                <img src={user.picture} alt={user.name} className="w-10 h-10 rounded-full mx-auto mb-2" />
              )}
              <p className="text-xs font-medium text-slate-600 truncate px-2">{user.name}</p>
            </div>
          )}
          <button
            onClick={handleLogout}
            className="flex flex-col items-center justify-center rounded-xl transition-all duration-200 h-[4.25rem] w-full max-w-[4.5rem] mx-auto text-slate-500 hover:bg-red-50 hover:text-red-600"
            title="Cerrar sesión"
          >
            <LogOut size={24} strokeWidth={2} className="mb-0.5" />
            <span className="text-[9px] font-semibold tracking-wide">Salir</span>
          </button>
        </div>
      </aside>
    </div>
  );
};

import React, { createContext, useEffect, useState, useContext, ReactNode } from 'react';

// === MODELOS (Entidades) ===

export interface Producto {
  id: string;
  nombre: string;
  cantidad: number;
  empresa: string;
  ganancia: number;
  fechaAsignacion: string;
  fechaTerminacion: string;
  estado: 'Pendiente' | 'En proceso' | 'Terminado';
}

export interface Empleado {
  id: string;
  nombre: string;
  cargo: string;
  documento: string;
  telefono: string;
  fechaIngreso: string;
  estado: 'Activo' | 'Inactivo';
}

export interface RegistroDiario {
  id: string;
  empleadoId: string;
  fecha: string;
  horaEntrada: string;
  horaSalida: string;
  unidadesTotales: number;
  unidadesBuenas: number; // Reemplaza la calificación 1-5 por número entero
  producciones?: ProduccionRegistro[];
}

/** Aporte del empleado vinculado a una orden creada en Producción (`Producto`). */
export interface ProduccionRegistro {
  productoId: string;
  unidadesTotales: number;
  unidadesBuenas: number;
}

export interface TareaAseo {
  id: string;
  accion: string; // Ej. Barrer, Trapear...
  area: string;   // Ej. Sala, Cocina...
  encargado: string;
  completada: boolean;
}

interface BootstrapResponse {
  productos: Producto[];
  empleados: Empleado[];
  registros: RegistroDiario[];
  tareasAseo: TareaAseo[];
}

// === TIPO DEL CONTEXTO ===

interface AppContextType {
  // Productos (Producción)
  productos: Producto[];
  agregarProducto: (prod: Omit<Producto, 'id'>) => void;
  editarProducto: (id: string, prod: Partial<Producto>) => void;
  eliminarProducto: (id: string) => void;

  // Empleados
  empleados: Empleado[];
  agregarEmpleado: (emp: Omit<Empleado, 'id'>) => void;
  editarEmpleado: (id: string, emp: Partial<Empleado>) => void;
  eliminarEmpleado: (id: string) => void;

  // Registros de Empleados
  registros: RegistroDiario[];
  agregarRegistro: (reg: Omit<RegistroDiario, 'id'>) => void;
  eliminarRegistro: (id: string) => void;

  // Aseo
  tareasAseo: TareaAseo[];
  agregarTareaAseo: (tarea: Omit<TareaAseo, 'id'>) => void;
  editarTareaAseo: (id: string, tarea: Partial<TareaAseo>) => void;
  toggleTareaAseo: (id: string) => void;
  eliminarTareaAseo: (id: string) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

/** En dev, Vite reenvía /api → backend (vite.config). En prod, define VITE_API_BASE_URL al desplegar el API. */
const fromEnv = import.meta.env.VITE_API_BASE_URL as string | undefined;
const API_BASE = fromEnv && fromEnv.trim() !== '' ? `${fromEnv.trim()}/api/frontend` : '/api/frontend';

const request = async <T,>(path: string, options?: RequestInit): Promise<T> => {
  console.log('API_BASE:', API_BASE);
  console.log('Full URL:', `${API_BASE}${path}`);
  const res = await fetch(`${API_BASE}${path}`, {
    headers: { 'Content-Type': 'application/json' },
    ...options,
  });
  console.log('Response status:', res.status);
  if (!res.ok) {
    const text = await res.text();
    console.error(`API ${res.status}: ${text || 'Error desconocido'}`);
    throw new Error(`API ${res.status}: ${text || 'Error desconocido'}`);
  }
  if (res.status === 204) return undefined as T;
  return res.json() as Promise<T>;
};

export const AppProvider = ({ children }: { children: ReactNode }) => {
  // === ESTADOS (Base de datos simulada) ===

  const [productos, setProductos] = useState<Producto[]>([]);
  const [empleados, setEmpleados] = useState<Empleado[]>([]);
  const [registros, setRegistros] = useState<RegistroDiario[]>([]);
  const [tareasAseo, setTareasAseo] = useState<TareaAseo[]>([]);

  useEffect(() => {
    let mounted = true;
    request<BootstrapResponse>('/bootstrap')
      .then((data) => {
        if (!mounted) return;
        setProductos(data.productos ?? []);
        setEmpleados(data.empleados ?? []);
        setRegistros(data.registros ?? []);
        setTareasAseo(data.tareasAseo ?? []);
      })
      .catch((err) => {
        console.warn('No se pudo cargar bootstrap del backend:', err);
      });
    return () => {
      mounted = false;
    };
  }, []);

  // === FUNCIONES CRUD ===

  // Producción
  const agregarProducto = (prod: Omit<Producto, 'id'>) => {
    request<Producto>('/productos', {
      method: 'POST',
      body: JSON.stringify(prod),
    })
      .then((nuevo) => {
        setProductos((prev) => [nuevo, ...prev]);
      })
      .catch((err) => console.error('Error creando producto:', err));
  };
  const editarProducto = (id: string, prod: Partial<Producto>) => {
    const actual = productos.find((p) => p.id === id);
    if (!actual) return;
    const payload = { ...actual, ...prod };
    request<Producto>(`/productos/${id}`, {
      method: 'PUT',
      body: JSON.stringify(payload),
    })
      .then((actualizado) => {
        setProductos((prev) => prev.map((p) => (p.id === id ? actualizado : p)));
      })
      .catch((err) => console.error('Error editando producto:', err));
  };
  const eliminarProducto = (id: string) => {
    request<void>(`/productos/${id}`, { method: 'DELETE' })
      .then(() => {
        setProductos((prev) => prev.filter((p) => p.id !== id));
        setRegistros((prev) =>
          prev.map((r) => ({
            ...r,
            producciones: (r.producciones ?? []).filter((p) => p.productoId !== id),
          }))
        );
      })
      .catch((err) => console.error('Error eliminando producto:', err));
  };

  // Empleados
  const agregarEmpleado = (emp: Omit<Empleado, 'id'>) => {
    request<Empleado>('/empleados', {
      method: 'POST',
      body: JSON.stringify(emp),
    })
      .then((nuevo) => {
        setEmpleados((prev) => [nuevo, ...prev]);
      })
      .catch((err) => console.error('Error creando empleado:', err));
  };
  const editarEmpleado = (id: string, emp: Partial<Empleado>) => {
    const actual = empleados.find((e) => e.id === id);
    if (!actual) return;
    const payload = { ...actual, ...emp };
    request<Empleado>(`/empleados/${id}`, {
      method: 'PUT',
      body: JSON.stringify(payload),
    })
      .then((actualizado) => {
        setEmpleados((prev) => prev.map((e) => (e.id === id ? actualizado : e)));
      })
      .catch((err) => console.error('Error editando empleado:', err));
  };
  const eliminarEmpleado = (id: string) => {
    request<void>(`/empleados/${id}`, { method: 'DELETE' })
      .then(() => {
        setEmpleados((prev) => prev.filter((e) => e.id !== id));
        setRegistros((prev) => prev.filter((r) => r.empleadoId !== id));
      })
      .catch((err) => console.error('Error eliminando empleado:', err));
  };

  // Registros
  const agregarRegistro = (reg: Omit<RegistroDiario, 'id'>) => {
    request<RegistroDiario>('/registros', {
      method: 'POST',
      body: JSON.stringify(reg),
    })
      .then((nuevo) => {
        setRegistros((prev) => [nuevo, ...prev]);
      })
      .catch((err) => console.error('Error creando registro:', err));
  };
  const eliminarRegistro = (id: string) => {
    request<void>(`/registros/${id}`, { method: 'DELETE' })
      .then(() => {
        setRegistros((prev) => prev.filter((r) => r.id !== id));
      })
      .catch((err) => console.error('Error eliminando registro:', err));
  };

  // Aseo
  const agregarTareaAseo = (tarea: Omit<TareaAseo, 'id'>) => {
    request<TareaAseo>('/tareas-aseo', {
      method: 'POST',
      body: JSON.stringify(tarea),
    })
      .then((nueva) => {
        setTareasAseo((prev) => [nueva, ...prev]);
      })
      .catch((err) => console.error('Error creando tarea de aseo:', err));
  };
  const editarTareaAseo = (id: string, tarea: Partial<TareaAseo>) => {
    const actual = tareasAseo.find((t) => t.id === id);
    if (!actual) return;
    const payload = { ...actual, ...tarea };
    request<TareaAseo>(`/tareas-aseo/${id}`, {
      method: 'PUT',
      body: JSON.stringify(payload),
    })
      .then((actualizada) => {
        setTareasAseo((prev) => prev.map((t) => (t.id === id ? actualizada : t)));
      })
      .catch((err) => console.error('Error editando tarea de aseo:', err));
  };
  const toggleTareaAseo = (id: string) => {
    request<TareaAseo>(`/tareas-aseo/${id}/toggle`, {
      method: 'PATCH',
    })
      .then((actualizada) => {
        setTareasAseo((prev) => prev.map((t) => (t.id === id ? actualizada : t)));
      })
      .catch((err) => console.error('Error cambiando estado de tarea:', err));
  };
  const eliminarTareaAseo = (id: string) => {
    request<void>(`/tareas-aseo/${id}`, { method: 'DELETE' })
      .then(() => {
        setTareasAseo((prev) => prev.filter((t) => t.id !== id));
      })
      .catch((err) => console.error('Error eliminando tarea de aseo:', err));
  };

  return (
    <AppContext.Provider value={{
      productos, agregarProducto, editarProducto, eliminarProducto,
      empleados, agregarEmpleado, editarEmpleado, eliminarEmpleado,
      registros, agregarRegistro, eliminarRegistro,
      tareasAseo, agregarTareaAseo, editarTareaAseo, toggleTareaAseo, eliminarTareaAseo
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useAppContext = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useAppContext debe usarse dentro de un AppProvider');
  return context;
};

